// macOS process-local AU registration bypasses the system component registry.
#include <AudioToolbox/AudioToolbox.h>
#include <CoreFoundation/CoreFoundation.h>
#include <dlfcn.h>
#include <cmath>
#include <iostream>
#include <stdexcept>
#include <vector>
void ok(OSStatus status,const char* message){if(status)throw std::runtime_error(std::string(message)+": "+std::to_string(status));}
OSStatus source(void*,AudioUnitRenderActionFlags*,const AudioTimeStamp* t,UInt32,UInt32 frames,AudioBufferList* buffers){for(UInt32 b=0;b<buffers->mNumberBuffers;++b){auto* data=static_cast<float*>(buffers->mBuffers[b].mData);for(UInt32 i=0;i<frames;++i)data[i]=.1f*std::sin((t->mSampleTime+i)*6.283185307179586*300/48000);}return noErr;}
int main(int argc,char** argv){try{if(argc!=2)return 2;void* library=dlopen(argv[1],RTLD_NOW|RTLD_LOCAL);if(!library)throw std::runtime_error(dlerror());auto factory=reinterpret_cast<AudioComponentFactoryFunction>(dlsym(library,"FM_DELAYAUFactory"));if(!factory)throw std::runtime_error("AU factory export missing");AudioComponentDescription desc{kAudioUnitType_Effect,'FmDl','FmAu',0,0};auto component=AudioComponentRegister(&desc,CFSTR("FM Audio: FM DELAY isolated check"),0xa00,factory);if(!component)throw std::runtime_error("process-local component registration failed");AudioUnit unit=nullptr;ok(AudioComponentInstanceNew(component,&unit),"AU instance creation");AudioStreamBasicDescription format{};format.mSampleRate=48000;format.mFormatID=kAudioFormatLinearPCM;format.mFormatFlags=kAudioFormatFlagIsFloat|kAudioFormatFlagIsPacked|kAudioFormatFlagIsNonInterleaved;format.mBytesPerPacket=format.mBytesPerFrame=4;format.mFramesPerPacket=1;format.mChannelsPerFrame=2;format.mBitsPerChannel=32;ok(AudioUnitSetProperty(unit,kAudioUnitProperty_StreamFormat,kAudioUnitScope_Input,0,&format,sizeof(format)),"input format");ok(AudioUnitSetProperty(unit,kAudioUnitProperty_StreamFormat,kAudioUnitScope_Output,0,&format,sizeof(format)),"output format");AURenderCallbackStruct callback{source,nullptr};ok(AudioUnitSetProperty(unit,kAudioUnitProperty_SetRenderCallback,kAudioUnitScope_Input,0,&callback,sizeof(callback)),"input callback");ok(AudioUnitInitialize(unit),"initialize");struct {UInt32 count;AudioBuffer buffers[2];} storage{};storage.count=2;std::vector<float> left(512),right(512);storage.buffers[0]={1,512*4,left.data()};storage.buffers[1]={1,512*4,right.data()};float peak=0;for(int block=0;block<200;++block){AudioTimeStamp time{};time.mFlags=kAudioTimeStampSampleTimeValid;time.mSampleTime=block*512;AudioUnitRenderActionFlags flags=0;ok(AudioUnitRender(unit,&flags,&time,0,512,reinterpret_cast<AudioBufferList*>(&storage)),"render");for(float x:left){if(!std::isfinite(x))throw std::runtime_error("nonfinite AU output");peak=std::max(peak,std::abs(x));}}if(peak<.01f)throw std::runtime_error("silent AU output");ok(AudioUnitUninitialize(unit),"uninitialize");ok(AudioComponentInstanceDispose(unit),"dispose");std::cout<<"PASS: direct process-local AU factory load, stereo input/output, 200 audio blocks, finite audible output, clean disposal\n";}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
